ack: 'Back to overview', prev: 'Previous', next: 'Next', sources: 'Sources on the grid', offpeak: 'Off-peak', normal: 'Normal', peak: 'Peak hours', hpLoad: 'Heat pump consumption', more: 'More info', info: 'Product info',
